"use client";

import { useState, useMemo } from "react";
import { ChevronLeft, ChevronRight, X, Clock } from "lucide-react";
import { format, addMonths, subMonths, startOfMonth, endOfMonth, startOfWeek, endOfWeek, isSameMonth, addDays } from "date-fns";
import { nl } from "date-fns/locale"; 
import { createCalendarItem } from "@/app/actions/task-actions";
import { useRouter } from "next/navigation";

export default function CalendarClient({ initialTasks = [] }: { initialTasks: any[] }) {
  const router = useRouter();
  const [currentMonth, setCurrentMonth] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState<Date | null>(null);
  
  // Form Durumları
  const [loading, setLoading] = useState(false);
  const [title, setTitle] = useState("");
  const [time, setTime] = useState("12:00"); // Saat seçimi için
  const [type, setType] = useState("agenda");

  // VERİLERİ GÜNLERE DAĞITMA
  const taskMap = useMemo(() => {
    const map: any = {};
    initialTasks.forEach((item) => {
      // DİKKAT: Şemandaki 'startDatetime' ismini kullanıyoruz
      if (item.startDatetime) {
        const d = new Date(item.startDatetime);
        const dateKey = format(d, "yyyy-MM-dd");
        if (!map[dateKey]) map[dateKey] = [];
        map[dateKey].push(item);
      }
    });
    return map;
  }, [initialTasks]);

  const handleSave = async () => {
    if (!title || !selectedDate) return;
    setLoading(true);

    try {
      const res = await createCalendarItem({
        titel: title,
        documentType: type,
        datum: format(selectedDate, "yyyy-MM-dd"),
        uure: time // "14:30" gibi gider
      });

      if (res.success) {
        setTitle("");
        setSelectedDate(null);
        router.refresh(); // Sayfayı tazele
        setTimeout(() => window.location.reload(), 300);
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-[1400px] mx-auto p-6 text-white">
      {/* Ay Değiştirme */}
      <div className="flex justify-between items-center mb-8 bg-[#0a0e17] p-4 rounded-2xl border border-white/5">
        <button onClick={() => setCurrentMonth(subMonths(currentMonth, 1))} className="cursor-pointer text-teal-500"><ChevronLeft size={30}/></button>
        <h2 className="text-2xl font-black uppercase italic">{format(currentMonth, "MMMM yyyy", { locale: nl })}</h2>
        <button onClick={() => setCurrentMonth(addMonths(currentMonth, 1))} className="cursor-pointer text-teal-500"><ChevronRight size={30}/></button>
      </div>

      {/* Takvim Grid */}
      <div className="grid grid-cols-7 border border-white/10 rounded-3xl overflow-hidden bg-[#0a0e17]">
        {["Ma", "Di", "Wo", "Do", "Vr", "Za", "Zo"].map(d => (
          <div key={d} className="p-4 text-center text-[10px] font-black text-teal-500/40 border-b border-white/5 uppercase tracking-widest">{d}</div>
        ))}
        {(() => {
          const days = [];
          let day = startOfWeek(startOfMonth(currentMonth), { weekStartsOn: 1 });
          const endDate = endOfWeek(endOfMonth(currentMonth), { weekStartsOn: 1 });

          while (day <= endDate) {
            const dateKey = format(day, "yyyy-MM-dd");
            const dayTasks = taskMap[dateKey] || [];
            const isCurrentMonth = isSameMonth(day, currentMonth);
            const currentDay = day;

            days.push(
              <div 
                key={day.toString()} 
                onClick={() => setSelectedDate(currentDay)}
                className={`min-h-[140px] border border-white/5 p-2 hover:bg-white/[0.02] cursor-pointer ${!isCurrentMonth ? "opacity-5" : ""}`}
              >
                <div className="text-xs text-teal-500/20 mb-1">{format(day, "d")}</div>
                <div className="space-y-1">
                  {dayTasks.map((t: any) => (
                    <div key={t.id} className="text-[9px] p-1 bg-fuchsia-500/10 border border-fuchsia-500/20 rounded flex justify-between">
                      <span className="truncate">{t.title}</span>
                      <span className="text-fuchsia-500 font-mono">{format(new Date(t.startDatetime), "HH:mm")}</span>
                    </div>
                  ))}
                </div>
              </div>
            );
            day = addDays(day, 1);
          }
          return days;
        })()}
      </div>

      {/* SAAT SEÇİCİLİ FORM */}
      {selectedDate && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/80 backdrop-blur-md">
          <div className="bg-[#0E153A] border border-white/10 p-8 rounded-[32px] w-full max-w-sm relative">
            <button onClick={() => setSelectedDate(null)} className="absolute top-4 right-4 text-white/20 hover:text-white cursor-pointer"><X /></button>
            <p className="text-fuchsia-500 font-black text-[10px] uppercase mb-4 tracking-widest">Nieuw Item</p>
            
            <div className="space-y-4">
              <input 
                placeholder="Wat is de titel?" 
                value={title} onChange={(e) => setTitle(e.target.value)}
                className="w-full bg-[#070B24] border border-white/10 p-4 rounded-xl outline-none focus:border-fuchsia-500"
              />
              
              <div className="flex items-center gap-3 bg-[#070B24] border border-white/10 p-4 rounded-xl">
                <Clock className="text-teal-500" size={20} />
                <input 
                  type="time" 
                  value={time} onChange={(e) => setTime(e.target.value)}
                  className="bg-transparent text-white outline-none font-mono text-xl w-full"
                />
              </div>

              <div className="grid grid-cols-2 gap-2">
                {['agenda', 'assignment', 'meeting', 'daily'].map(cat => (
                  <button key={cat} onClick={() => setType(cat)} className={`py-2 text-[10px] font-black uppercase border rounded-lg transition-all ${type === cat ? 'bg-fuchsia-600 border-fuchsia-600 text-white' : 'bg-[#070B24] border-white/5 text-white/40'}`}>{cat}</button>
                ))}
              </div>

              <button 
                onClick={handleSave} 
                disabled={loading || !title}
                className="w-full bg-white text-black font-black py-4 rounded-xl uppercase text-xs tracking-widest mt-4 hover:bg-fuchsia-500 hover:text-white transition-all"
              >
                {loading ? "Opslaan..." : "Bevestigen"}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}